package au.aumanet.app;import android.content.Context;import java.util.*;final class GroupTextAndroidDatabase implements GroupTextDatabase{final GroupMessagesStoreTest.Jdbc db;GroupTextAndroidDatabase(Context context)throws Exception{db=new GroupMessagesStoreTest.Jdbc(context.getNoBackupFilesDir().getName()+"-worker.sqlite");}public void exec(String sql,Object...args)throws Exception{db.exec(sql,args);}public List<Map<String,Object>> rows(String sql,String...args)throws Exception{return db.rows(sql,args);}public void begin()throws Exception{db.begin();}public void commit()throws Exception{db.commit();}public void rollback()throws Exception{db.rollback();}public void close()throws Exception{db.close();}}
